            const id = el.getAttribute('id');
            const name = el.getAttribute('name');
            if (id) return '#' + id;
            if (name) return el.tagName.toLowerCase() + '[name="' + name + '"]';
            return el.tagName.toLowerCase() + (el.getAttribute('type') ? '[type="' + el.getAttribute('type') + '"]' : '');
