        test.skip(forms.length === 0, 'no form with two or more fields on /product/01M5EHR5FT6FEPQ48PRF8BCYXH');
        const problems: string[] = [];
        const positive = fields.filter((field) => forms.includes(field.form) && field.tabIndex > 0);
