      const { page, response } = await tfShared.visit('/product/01M5EHR5FT6FEPQ48PRF8BCYXH');
      const notAPage = response ? tfNotAPage(response.status()) : null;
      test.skip(notAPage !== null, '/product/01M5EHR5FT6FEPQ48PRF8BCYXH ' + notAPage);
      await page.waitForLoadState('load');
